//! Contract tests against the Python-built mini snapshot fixture.
//!
//! The fixture is generated by the pipeline (`build --subset mini`) and is the
//! same binary file the shipping app will read. These tests prove the Rust
//! reader accepts a real schema-v1 database and rejects damaged ones.

use std::fs;
use std::path::{Path, PathBuf};

use indicators_core::adapters::sqlite_snapshot::SqliteSnapshotOpener;
use indicators_core::domain::CoreError;
use indicators_core::ports::SnapshotOpener;

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/mini.snapshot.sqlite")
}

fn open_error(path: &Path) -> CoreError {
    match SqliteSnapshotOpener.open(path) {
        Ok(_) => panic!("{} should have been rejected", path.display()),
        Err(error) => error,
    }
}

fn copy_fixture(directory: &Path, name: &str) -> PathBuf {
    let target = directory.join(name);
    fs::copy(fixture(), &target).expect("fixture must be copyable");
    target
}

#[test]
fn reads_dataset_info_from_the_python_built_fixture() {
    let reader = SqliteSnapshotOpener
        .open(&fixture())
        .expect("mini fixture must open");

    let info = reader.info().unwrap();

    assert_eq!(info.schema_version, 1);
    assert_eq!(info.origin, "worldbank");
    assert_eq!(info.dataset_id, "ecuador-indicators");
    assert_eq!(info.source_name, "World Development Indicators");
    assert_eq!(info.source_publisher, "The World Bank");
    assert_eq!(info.license, "CC-BY-4.0");
    assert_eq!(
        info.license_url,
        "https://creativecommons.org/licenses/by/4.0/"
    );
    assert!(info.attribution_en.contains("CC BY 4.0"));
    assert!(info.attribution_es.contains("CC BY 4.0"));
    assert_eq!(info.source_last_updated, "2026-11-11");
    assert!(!info.retrieved_at.is_empty());
    assert_eq!(
        info.counts,
        indicators_core::domain::DatasetCounts {
            topics: 3,
            geographies: 5,
            indicators: 6,
            observations: 1_524,
        }
    );
}

#[test]
fn reads_the_catalog_with_both_languages_and_sort_order() {
    let reader = SqliteSnapshotOpener.open(&fixture()).unwrap();

    let catalog = reader.catalog().unwrap();

    assert_eq!(catalog.topics.len(), 3);
    assert_eq!(catalog.geographies.len(), 5);
    assert_eq!(catalog.indicators.len(), 6);
    assert_eq!(catalog.topics[0].id, "economy");
    assert_eq!(catalog.topics[0].name_en, "Economy & prices");
    assert_eq!(catalog.geographies[0].iso3, "ECU");
    assert_eq!(catalog.geographies[0].iso2, "EC");
    assert!(
        catalog
            .geographies
            .iter()
            .find(|g| g.iso3 == "WLD")
            .unwrap()
            .is_aggregate
    );
    let gdp = catalog
        .indicators
        .iter()
        .find(|i| i.code == "NY.GDP.MKTP.CD")
        .unwrap();
    assert_eq!(gdp.name_en, "GDP (current US$)");
    assert_eq!(gdp.name_es, "PIB (US$ a precios actuales)");
    assert_eq!(gdp.unit_en, "current US$");
    assert_eq!(gdp.value_kind, indicators_core::domain::ValueKind::Currency);
    assert_eq!(gdp.decimals, 0);
    let sorted: Vec<i32> = catalog.indicators.iter().map(|i| i.sort_order).collect();
    let mut expected = sorted.clone();
    expected.sort_unstable();
    assert_eq!(sorted, expected);
}

#[test]
fn filters_observations_by_codes_and_geographies_in_stable_order() {
    let reader = SqliteSnapshotOpener.open(&fixture()).unwrap();

    let one = reader
        .observations(&["NY.GDP.MKTP.CD".to_string()], &["ECU".to_string()])
        .unwrap();
    assert_eq!(one.len(), 66);
    assert!(one.iter().all(|o| o.indicator_code == "NY.GDP.MKTP.CD"));
    assert!(one.iter().all(|o| o.iso3 == "ECU"));
    assert!(one.windows(2).all(|pair| pair[0].year < pair[1].year));

    let two = reader
        .observations(
            &["NY.GDP.MKTP.CD".to_string(), "SP.DYN.LE00.IN".to_string()],
            &["ECU".to_string(), "COL".to_string()],
        )
        .unwrap();
    assert_eq!(two.len(), 262);

    assert!(
        reader
            .observations(&[], &["ECU".to_string()])
            .unwrap()
            .is_empty()
    );
    assert!(
        reader
            .observations(&["NY.GDP.MKTP.CD".to_string()], &[])
            .unwrap()
            .is_empty()
    );
}

#[test]
fn rejects_a_snapshot_with_the_wrong_schema_version() {
    let directory = tempfile::tempdir().unwrap();
    let path = copy_fixture(directory.path(), "wrong-version.sqlite");
    let connection = rusqlite::Connection::open(&path).unwrap();
    connection.pragma_update(None, "user_version", 2).unwrap();
    drop(connection);

    let error = open_error(&path);

    assert_eq!(error.code(), "SNAPSHOT_INVALID");
    assert!(error.to_string().contains("schema version"));
}

#[test]
fn rejects_a_snapshot_missing_a_required_table() {
    let directory = tempfile::tempdir().unwrap();
    let path = copy_fixture(directory.path(), "missing-table.sqlite");
    let connection = rusqlite::Connection::open(&path).unwrap();
    connection.execute_batch("DROP TABLE observation;").unwrap();
    drop(connection);

    let error = open_error(&path);

    assert_eq!(error.code(), "SNAPSHOT_INVALID");
    assert!(error.to_string().contains("observation"));
}

#[test]
fn rejects_a_corrupt_file() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("corrupt.sqlite");
    fs::write(&path, b"this is definitely not a sqlite database").unwrap();

    let error = open_error(&path);

    assert_eq!(error.code(), "SNAPSHOT_INVALID");
}

#[test]
fn reports_a_missing_snapshot_separately() {
    let directory = tempfile::tempdir().unwrap();
    let path = directory.path().join("nope.sqlite");

    let error = open_error(&path);

    assert_eq!(error.code(), "SNAPSHOT_NOT_FOUND");
}
